export type OrganizationLicenseInstantiateRequest = {
    /**
     * The license template to copy. It is read once, here. The organization keeps the copy, so editing this template afterwards does not reach them.
     */
    template_id: Ksuid;
};

/**
 * An adjustment to one organization's license. Use it for a bespoke arrangement that does not deserve a new tier.
 */
export type OrganizationLicenseAdjustRequest = {
    /**
     * Merged into the license, not substituted for it. A license field present replaces the value held. A license field absent keeps its value, which is the opposite of a template write — a template is authored whole, a license is adjusted one field at a time. No license field can be removed this way, because every field the schema declares must stay set. The merged result is validated against the schema exactly as a template write is.
     */
    values: LicenseTemplateValues;
};

/**
 * An organization's license: its own copy of a template's values. Every license field the schema declares carries a value, so a consumer can read it at face value.
 */
export type OrganizationLicenseResponse = {
    id: Ksuid;
    product_id: Ksuid;
    organization_id: Ksuid;
    /**
     * Which template this organization was sold. Provenance, not a live dependency: the template can be edited or deleted afterwards without changing `values`, and it may no longer exist.
     */
    template_id: Ksuid;
    /**
     * When the copy was taken. An adjustment does not move it.
     */
    instantiated_at: string;
    /**
     * What this organization is allowed, keyed by license field name. A value that differs from the template is a deviation — read the diff route to find them.
     */
    values: LicenseTemplateValues;
    /**
     * One entry per limit field the product's license schema declares, keyed by license field name — every declared field that is not a limit never appears here. Present on the license read, where it is computed fresh on every call; absent from the response to instantiating or adjusting a license, which does not compute it.
     */
    usage?: {
        [key: string]: LicenseFieldUsageResponse;
    };
    created_at: string;
    updated_at: string;
};

/**
 * A limit field's derived state against its latest reported usage. Computed on every license read and never stored. `stale` means the field has never been reported against, so there is no current number to trust. Anchor advises with this value; it never gates on it.
 */
export enum LicenseUsageStatus {
    WITHIN_LIMIT = 'within_limit',
    AT_LIMIT = 'at_limit',
    EXCEEDED = 'exceeded',
    STALE = 'stale'
}

/**
 * One limit field's latest reported usage and derived status, as read from an organization's license.
 */
export type LicenseFieldUsageResponse = {
    /**
     * This organization's current value for the field, mirroring `values` on the enclosing license.
     */
    limit: number;
    /**
     * The latest reported value, or null if never reported.
     */
    usage?: number;
    status: LicenseUsageStatus;
    /**
     * When the latest usage observation was recorded. Null exactly when `usage` is null.
     */
    last_reported_at?: string;
};

/**
 * Why a license field appears in a diff. `changed` means the two sides hold different values — either someone adjusted this organization, or the template moved after the copy was taken. The kind alone does not say which. `only_in_license` and `only_in_template` always mean the template changed shape after the copy.
 */
export enum LicenseDifferenceKind {
    CHANGED = 'changed',
    ONLY_IN_LICENSE = 'only_in_license',
    ONLY_IN_TEMPLATE = 'only_in_template'
}

export type LicenseFieldDifference = {
    /**
     * The license field the two sides disagree on.
     */
    field: string;
    kind: LicenseDifferenceKind;
    /**
     * The value the organization's license holds. Null when the kind is `only_in_template`, because the template gained this license field after the copy was taken.
     */
    license_value: unknown;
    /**
     * The value the template holds today. Null when the kind is `only_in_license`, because the template dropped this license field after the copy was taken.
     */
    template_value: unknown;
};

/**
 * How an organization's license differs from its template today. Templates carry no version, so this names which license fields differ rather than which revision they came from.
 */
export type OrganizationLicenseDiffResponse = {
    organization_id: Ksuid;
    template_id: Ksuid;
    /**
     * Ordered by license field name.
     */
    differences: Array<LicenseFieldDifference>;
    count: number;
};

/**
 * What happened to an organization's license. `INSTANTIATED` is a template being stamped onto the organization through the single-organization license route: `template_id` names it and `new_value` carries the whole set of values copied. `ADJUSTED` is one license field moved for this organization alone: `field` names it, and `old_value` and `new_value` are that field's values on either side of the change. `SET` is the organization's license set through the batch migrate route — moved from another template, or granted its first, whichever it held before the run: `template_id` names the template it now holds, `previous_template_id` the one it came from (absent for a first license), and `old_value` and `new_value` carry the whole set of values on either side (`old_value` absent to match).
 */
export enum LicenseChangeType {
    INSTANTIATED = 'INSTANTIATED',
    ADJUSTED = 'ADJUSTED',
    SET = 'SET'
}

/**
 * One entry in an organization's license history. Entries are immutable and append-only: nothing edits one, and a correction is a later entry.
 */
export type OrganizationLicenseChangeResponse = {
    id: Ksuid;
    product_id: Ksuid;
    organization_id: Ksuid;
    /**
     * Which license record was changed. Provenance, not a live dependency: the entry stays true whatever becomes of that record.
     */
    license_id: Ksuid;
    type: LicenseChangeType;
    /**
     * The template stamped onto the organization. Present when `type` is `INSTANTIATED` or `SET`, absent otherwise.
     */
    template_id?: Ksuid;
    /**
     * The template the organization held before it was moved. Present when `type` is `SET` and the organization held a license before this run, absent otherwise — including a `SET` entry that granted a first license.
     */
    previous_template_id?: Ksuid;
    /**
     * The license field that moved. Present when `type` is `ADJUSTED`, absent otherwise.
     */
    field?: string;
    /**
     * The value held before the change: that license field's value for an adjustment, and the whole set held before the move for a `SET` entry that moved an existing license. Absent when `type` is `INSTANTIATED`, when an adjustment set a license field the license did not carry, and when a `SET` entry granted a first license.
     */
    old_value?: unknown;
    /**
     * The value held after the change: that license field's value for an adjustment, and the whole set of copied values for an instantiation or a `SET` entry.
     */
    new_value?: unknown;
    /**
     * When the change was recorded. Anchor sets it. Every entry of one adjustment shares it, so an adjustment that touched several license fields reads back as one moment. Every organization set by one migration run shares it too, which together with `template_id` is what identifies a run.
     */
    changed_at: string;
};

/**
 * What to do with a license field whose value differs from the template the organization currently holds. `CARRY_FORWARD`, the default, keeps that value on the migrated license, so a bespoke arrangement survives a tier change. `DISCARD` takes the target template whole and the value is gone.
 * A difference is either someone adjusting that customer or the template moving after the copy was taken, and the difference alone does not say which. `CARRY_FORWARD` therefore preserves a stale copy as readily as a bespoke deal. Read the diff between the two templates before choosing.
 */
export enum LicenseMigrationDifferencePolicy {
    CARRY_FORWARD = 'CARRY_FORWARD',
    DISCARD = 'DISCARD'
}

/**
 * What happened to one organization in a migration run. `CHANGED` means its license was written and its provenance stamped onto the target — moved from another tier, or granted its first, whichever it held before the run; `previous_template_id` on the history entry says which. `UNCHANGED` means it already held exactly those values from that same template, so nothing was written. `FAILED` means the write was attempted and refused; `error` says why, and the rest of the batch was unaffected.
 */
export enum LicenseMigrationOutcome {
    CHANGED = 'CHANGED',
    UNCHANGED = 'UNCHANGED',
    FAILED = 'FAILED'
}

/**
 * Moves a set of organizations onto one license template. Each license takes the target template's values and its provenance is restamped, so the record says which tier the customer is on now. This is not an adjustment: adjusting cannot move provenance, by design.
 * By default a value that differs from the template the organization currently holds is carried forward onto the new license, so a bespoke arrangement survives the move. See `on_difference`.
 * Supply exactly one selection — `organization_ids` or `from_template_id`. Supplying both, or neither, is refused.
 */
export type OrganizationLicenseMigrationRequest = {
    /**
     * The template to move onto. It must be active: a withdrawn tier cannot be sold to anyone, which is the same rule instantiation follows.
     */
    template_id: Ksuid;
    /**
     * The organizations to move, named explicitly. An identifier naming no organization in this product is reported as a failed result rather than failing the batch.
     */
    organization_ids?: Array<Ksuid>;
    /**
     * Move every organization in this product whose license names this template. Archived is accepted and is the common case: this is how a withdrawn tier is emptied. Resolved inside the request, so an organization instantiated a moment ago cannot be missed by a client that listed first.
     */
    from_template_id?: Ksuid;
    on_difference?: LicenseMigrationDifferencePolicy;
};

/**
 * What one migration did to one organization.
 */
export type OrganizationLicenseMigrationResult = {
    organization_id: Ksuid;
    outcome: LicenseMigrationOutcome;
    /**
     * The template the organization held before this run. Absent when it held no license — this run granted its first, rather than moving it.
     */
    previous_template_id?: Ksuid;
    /**
     * What the run actually did to this organization's license, one field at a time, ordered by name. `license_value` is the value held before, `template_value` the value held after. A field carried forward under `CARRY_FORWARD` does not appear, because it did not move. An organization granted a first license reports every field the target names, since none was held before. Empty when nothing changed.
     */
    changes: Array<LicenseFieldDifference>;
    /**
     * The number of entries in `changes`.
     */
    count: number;
    /**
     * Present when `outcome` is `FAILED`, absent otherwise.
     */
    error?: ApiError;
};

/**
 * The receipt for one migration run: every organization it considered and what happened to each. Results are ordered by organization identifier.
 */
export type OrganizationLicenseMigrationResponse = {
    /**
     * The template every changed organization now holds.
     */
    template_id: Ksuid;
    /**
     * The single moment stamped on every organization this run set, and recorded as `changed_at` on every history entry it appended. Together with `template_id` it identifies the run.
     */
    migrated_at: string;
    results: Array<OrganizationLicenseMigrationResult>;
    /**
     * The number of organizations considered.
     */
    count: number;
    changed: number;
    unchanged: number;
    failed: number;
};

/**
 * Narrows a search over a product's organizations and the licenses they hold.
 */
export type OrganizationLicenseFilter = {
    organization_ids?: Array<Ksuid>;
    /**
     * Keep only organizations whose license names one of these templates. An archived template is accepted, and asking for one is how an operator finds the customers still on a withdrawn tier.
     */
    license_template_ids?: Array<Ksuid>;
    /**
     * `true` keeps only organizations that hold a license, `false` only those that hold none. Omit for both.
     */
    licensed?: boolean;
};

/**
 * Field to sort by. `instantiated_at` puts organizations holding no license last, because they were never stamped.
 */
export enum OrganizationLicenseSortField {
    ORGANIZATION_NAME = 'organization_name',
    INSTANTIATED_AT = 'instantiated_at'
}

export type OrganizationLicenseSearchRequest = SearchRequest & {
    filter?: OrganizationLicenseFilter;
    sort_by?: OrganizationLicenseSortField;
};

/**
 * One of the product's organizations and the license it holds, if any. The organization is the subject: one that has never been licensed is listed with `license` absent rather than omitted from the results, because an unlicensed customer is exactly what an operator is looking for half the time.
 */
export type OrganizationLicenseSummaryResponse = {
    organization_id: Ksuid;
    organization_name: string;
    /**
     * Absent when the organization holds no license. `usage` is never populated here — deriving it per row would make a page of results as expensive as a page of license reads.
     */
    license?: OrganizationLicenseResponse;
};

export type OrganizationLicenseSearchResponse = PagedListResponse & {
    items: Array<OrganizationLicenseSummaryResponse>;
};

export type OrganizationLicenseHistoryResponse = PagedListResponse & {
    /**
     * Newest first.
     */
    items: Array<OrganizationLicenseChangeResponse>;
};

/**
 * One absolute snapshot of what an organization has used. Report as often as you like — the cadence is your decision, not a contract shared with Anchor. Anchor stores every report and never adds them together, so a retry cannot double-count, and a report that never arrived corrects itself on the next one.
 */
export type UsageReportRequest = {
    /**
     * The license field this value is measured against. The product's license schema must declare it, and it must be a limit. A boolean feature toggle carries no usage. The field also declares a usage shape — GAUGE or WINDOWED_COUNTER — and this report must carry a window if and only if the field is WINDOWED_COUNTER.
     */
    key: string;
    /**
     * The total right now, not the change since the last report. It must be a finite, non-negative number. That is the only bound. A value past the organization's limit is accepted and stored, because refusing it would hide the fact that the limit was passed.
     */
    value: number;
    /**
     * Send no window at all to report a gauge: "37 flows exist right now", a number that rises and falls. Send `from` to report a counter over the half-open period [from, to): "412 runs between August 14 and September 14". Start a new window to reset the counter.
     * The period is two timestamps rather than a formatted string, because real billing periods follow the subscription anniversary rather than the calendar.
     */
    from?: string;
    /**
     * The exclusive end of the period. It must come after `from`, and no more than one year after it.
     * Omit it to mean now. "412 runs since August 14" is a complete statement, and sending a timestamp that means "now" only invites clock skew. Anchor fills the value in and returns it.
     * Sending `to` without `from` is refused. There is nothing to run from.
     */
    to?: string;
};

/**
 * One stored usage report. An observation is immutable. A correction is a new observation, never an edit of this one.
 */
export type UsageObservationResponse = {
    id: Ksuid;
    product_id: Ksuid;
    organization_id: Ksuid;
    /**
     * The license field this value was measured against.
     */
    key: string;
    value: number;
    /**
     * Both `from` and `to` are absent on a gauge, and both are present on a windowed counter. A report that sent `from` alone reads back with the `to` Anchor filled in, so a reader never meets half a window.
     */
    from?: string;
    to?: string;
    /**
     * When Anchor accepted the report. Anchor sets it, so a consumer cannot backdate a report or write into the future.
     */
    observed_at: string;
};

/**
 * Which level of the continuous-aggregate cascade to read. Every level reports the last observation per bucket — never a sum or an average, because the underlying values are snapshots and the last one in a bucket already is the bucket's value. Finer levels are retained for a shorter time than coarser ones; see docs/adr/0005-timescaledb-for-usage-history.md.
 */
export enum UsageGranularity {
    MINUTE = 'MINUTE',
    HOUR = 'HOUR',
    DAY = 'DAY'
}

/**
 * One bucket of an organization's usage series.
 */
export type UsageSeriesPointResponse = {
    /**
     * The start of this bucket, at the requested granularity.
     */
    bucket: string;
    /**
     * The last observation's value in this bucket.
     */
    value: number;
    /**
     * Present when the observation the bucket was built from was a windowed counter, absent for a gauge — carried through the aggregate unchanged from the underlying report.
     */
    from?: string;
    to?: string;
};

export type UsageSeriesResponse = PagedListResponse & {
    items: Array<UsageSeriesPointResponse>;
};

